BASE:
*{margin:0;padding:0;box-sizing:border-box}
:root{--brand:#123C32;--brand2:#1B5140;--accent:#B8893B;--accent2:#C09B4F;
--bg:#F5F4EF;--surf:#FFF;--surf2:#FAF9F4;--line:#DDD9CB;
--ink:#16211C;--ink2:#4A544E;--muted:#7A8480;
--ok:#2E7D5B;--okbg:#DCECE4;--warn:#C56A28;--warnbg:#F8E4D4;
--info:#3A5C8F;--infobg:#E3EAF5;--danger:#9C3B32;--dangerbg:#F6DFDC;
--dirty:#8A8F88;--dirtybg:#ECEAE1}
body.dark{--bg:#0E1613;--surf:#16211D;--surf2:#1B2823;--line:#2A3A34;
--ink:#E8EDE9;--ink2:#B4C0BA;--muted:#7E8C86;--okbg:#153A2C;--warnbg:#3E2716;
--infobg:#1A2740;--dangerbg:#3A1E1B;--dirtybg:#232B27;--ok:#5BC192;--warn:#E29556;
--info:#7FA3DC;--danger:#D98B80;--dirty:#9AA39C}
body{font-family:"Hiragino Sans","Yu Gothic UI","Noto Sans JP","Noto Sans Myanmar","Noto Sans Devanagari",sans-serif;
background:#0B0F0D;color:var(--ink);line-height:1.6}
.ctl{position:sticky;top:0;z-index:99;background:#080C0A;border-bottom:1px solid #1E2A25;
padding:11px 18px;display:flex;gap:12px;align-items:center;flex-wrap:wrap}
.lg{font-size:14px;font-weight:800;color:#E8EDE9}.lg em{color:var(--accent2);font-style:normal}
.bt{font-size:10.5px;color:#00A8A8;background:#0d2622;padding:3px 9px;border-radius:5px;font-weight:700}
.grp{display:flex;gap:4px;background:#111815;padding:4px;border-radius:8px;flex-wrap:wrap}
.gb{padding:6px 10px;border:none;border-radius:6px;background:transparent;color:#8C9A93;
font-size:11px;cursor:pointer;font-family:inherit;font-weight:600;white-space:nowrap}
.gb.on{background:var(--accent);color:#1A1206}
.gb.st.on{background:var(--brand2);color:#fff}
.gl{font-size:10px;color:#5D6B64;align-self:center}
.dm{margin-left:auto;padding:6px 12px;border-radius:7px;border:1px solid #2A3A34;
background:#111815;color:#9BA8A1;font-size:11.5px;cursor:pointer;font-family:inherit}
.page{padding:24px 20px;max-width:1200px;margin:0 auto}
.hd h1{font-size:20px;color:#E8EDE9;margin-bottom:5px}
.hd p{font-size:12.5px;color:#7E8C86;margin-bottom:20px;line-height:1.7}
.row{display:flex;gap:24px;flex-wrap:wrap;align-items:flex-start}
.ph{width:318px;border-radius:33px;padding:11px;background:var(--brand);
box-shadow:0 16px 50px rgba(0,0,0,.62);flex-shrink:0}
.sc{background:var(--bg);border-radius:24px;overflow:hidden;height:690px;
display:flex;flex-direction:column;color:var(--ink);position:relative}
.top{background:var(--brand);color:#fff;padding:12px 14px}
.top .a{font-size:14px;font-weight:700;display:flex;align-items:center;gap:8px}
.top .a .bk{opacity:.85;font-size:16px;cursor:pointer}
.top .b{font-size:10.5px;color:#B9CFC2;margin-top:3px}
.bd{flex:1;padding:12px;overflow-y:auto}
.bd::-webkit-scrollbar{width:4px}
.bd::-webkit-scrollbar-thumb{background:var(--line);border-radius:2px}
.ft{display:flex;background:var(--surf);border-top:1px solid var(--line)}
.ft div{flex:1;text-align:center;padding:10px 0 8px;font-size:9.5px;color:var(--muted);cursor:pointer}
.ft div .i{display:block;font-size:20px;margin-bottom:2px}
.ft div.on{color:var(--brand);font-weight:700}
body.dark .ft div.on{color:var(--ok)}
.big{width:100%;padding:19px;border-radius:12px;border:none;font-size:17px;font-weight:800;
cursor:pointer;font-family:inherit;background:var(--brand);color:#fff;
display:flex;align-items:center;justify-content:center;gap:9px;transition:.12s}
.big:active{transform:scale(.98)}
.big.w{background:var(--warn)}.big.r{background:var(--danger)}.big.g{background:var(--ok)}
.big.o{background:transparent;border:2px solid var(--line);color:var(--ink2);font-size:14px;padding:14px}
.big.dis{opacity:.35;cursor:not-allowed}
.two{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-top:9px}
.sec{font-size:11.5px;font-weight:800;color:var(--muted);margin:16px 0 8px;
display:flex;align-items:center;justify-content:space-between}
.sec .cn{font-weight:700}
.cd{background:var(--surf);border:1px solid var(--line);border-radius:11px;padding:14px;margin-bottom:11px}
.cd h4{font-size:12.5px;margin-bottom:10px;color:var(--ink2)}
.rw{display:flex;justify-content:space-between;align-items:center;padding:9px 0;
border-bottom:1px solid var(--line);font-size:12.5px}
.rw:last-child{border:0}.rw b{font-variant-numeric:tabular-nums}
.al{border-radius:11px;padding:13px;margin:11px 0;font-size:11.5px;line-height:1.65}
.al.w{background:var(--warnbg);border:1px solid var(--warn);color:var(--warn)}
.al.r{background:var(--dangerbg);border:1px solid var(--danger);color:var(--danger)}
.al.i{background:var(--infobg);border:1px solid var(--info);color:var(--info)}
.al.g{background:var(--okbg);border:1px solid var(--ok);color:var(--ok)}
.al b{display:block;margin-bottom:4px;font-size:12.5px}
.panel{flex:1;min-width:330px}
.card{background:#111815;border:1px solid #1E2A25;border-radius:11px;padding:17px;margin-bottom:14px}
.card h3{font-size:13.5px;color:#E8EDE9;margin-bottom:11px}
.card p{font-size:12.5px;color:#A8B5AE;line-height:1.75;margin-bottom:9px}
.card p:last-child{margin-bottom:0}
.card b{color:var(--accent2)}
.card code{background:#0A100D;padding:1px 6px;border-radius:3px;font-size:11px;color:var(--accent2)}
.card ul{list-style:none;margin-top:8px}
.card li{font-size:12px;color:#A8B5AE;padding:6px 0 6px 20px;position:relative;line-height:1.6}
.card li:before{content:"\u25b8";position:absolute;left:2px;color:var(--accent)}
table{width:100%;border-collapse:collapse;font-size:11.5px;margin-top:9px}
th{background:#16211D;color:#8C9A93;padding:8px 9px;border:1px solid #243029;text-align:left}
td{background:#0E1613;color:#B4C0BA;padding:8px 9px;border:1px solid #243029}
.hint{background:#0A100D;border-left:3px solid var(--accent);padding:10px 13px;
font-size:11.5px;color:#9BA8A1;margin-top:11px;line-height:1.65}
.rmk{background:#2a1a18;border-left:3px solid var(--danger);padding:10px 13px;
font-size:11.5px;color:#e0b5ae;margin-top:11px;line-height:1.65}
.fx{color:#5BC192}.nx{color:#D98B80}
.q{font-size:14px;font-weight:700;margin:14px 0 10px;display:flex;align-items:center;gap:7px}
.q .rq{font-size:9.5px;background:var(--dangerbg);color:var(--danger);padding:2px 7px;border-radius:4px}
.q .op{font-size:9.5px;background:var(--dirtybg);color:var(--dirty);padding:2px 7px;border-radius:4px}
.pk{display:grid;gap:8px;margin-bottom:16px}
.pk.c2{grid-template-columns:repeat(2,1fr)}.pk.c3{grid-template-columns:repeat(3,1fr)}
.pk.c4{grid-template-columns:repeat(4,1fr)}
.pk .o{padding:16px 5px;border-radius:12px;border:2.5px solid var(--line);background:var(--surf);
text-align:center;cursor:pointer;min-height:74px;
display:flex;flex-direction:column;align-items:center;justify-content:center;gap:5px}
.pk .o:active{transform:scale(.96)}
.pk .o .i{font-size:25px;line-height:1}
.pk .o .x{font-size:11px;font-weight:700;color:var(--ink2);line-height:1.2}
.pk .o.on{border-color:var(--brand);background:var(--okbg)}
.pk .o.on .x{color:var(--brand)}
body.dark .pk .o.on .x{color:var(--ok)}
.st{display:flex;align-items:center;justify-content:space-between;background:var(--surf);
border:1px solid var(--line);border-radius:12px;padding:11px 12px;margin-bottom:9px}
.st .lb{font-size:13px;font-weight:600;display:flex;align-items:center;gap:8px}
.st .lb .e{font-size:19px}
.st .ct{display:flex;align-items:center;gap:11px}
.st .mb{width:46px;height:46px;border-radius:11px;border:1.5px solid var(--line);
background:var(--surf2);font-size:23px;font-weight:800;color:var(--ink2);cursor:pointer;
font-family:inherit;line-height:1}
.st .mb:active{background:var(--okbg);border-color:var(--brand)}
.st .vv{font-size:23px;font-weight:800;min-width:36px;text-align:center;font-variant-numeric:tabular-nums}
.st .vv.zero{color:var(--muted)}
.tg2{display:flex;align-items:center;justify-content:space-between;background:var(--surf);
border:1px solid var(--line);border-radius:12px;padding:12px;margin-bottom:9px;cursor:pointer}
.tg2 .lb{font-size:13px;font-weight:600;display:flex;align-items:center;gap:8px}
.tg2 .sw{width:52px;height:30px;border-radius:16px;background:var(--dirtybg);
position:relative;transition:.2s;flex-shrink:0}
.tg2 .sw:after{content:"";position:absolute;top:3px;left:3px;width:24px;height:24px;
border-radius:50%;background:#fff;transition:.2s;box-shadow:0 1px 3px rgba(0,0,0,.2)}
.tg2.on .sw{background:var(--ok)}.tg2.on .sw:after{left:25px}
.ck{display:flex;align-items:center;gap:11px;background:var(--surf);border:1px solid var(--line);
border-radius:11px;padding:13px;margin-bottom:8px;cursor:pointer}
.ck .bx{width:28px;height:28px;border-radius:8px;border:2px solid var(--line);flex-shrink:0;
display:flex;align-items:center;justify-content:center;font-size:16px;font-weight:800}
.ck.on .bx{background:var(--ok);border-color:var(--ok);color:#fff}
.ck.on{background:var(--okbg);border-color:var(--ok)}
.ck .tx{font-size:12.5px;flex:1}
.ck .cm{font-size:10px;font-weight:700;padding:3px 7px;border-radius:5px;
background:var(--dangerbg);color:var(--danger);white-space:nowrap}
.ck .cm.ok{background:var(--okbg);color:var(--ok)}
.ck.fl{background:var(--dangerbg);border-color:var(--danger);border-width:2px}
.ph2{display:grid;grid-template-columns:repeat(4,1fr);gap:7px}
.ph2 .p{aspect-ratio:1;border-radius:9px;background:var(--surf2);border:1px solid var(--line);
display:flex;align-items:center;justify-content:center;font-size:19px;color:var(--muted);cursor:pointer}
.ph2 .p.has{background:var(--okbg);border-color:var(--ok);color:var(--ok)}
.ph2 .p.add{border:2px dashed var(--line);font-size:22px}
.tb{border-radius:14px;padding:15px;margin-bottom:11px;border:2px solid var(--line);background:var(--surf)}
.tb.run{border-color:var(--warn);background:var(--warnbg)}
.tb.rwk{border-color:var(--danger);background:var(--dangerbg)}
.tb.dn{border-color:var(--ok);background:var(--okbg)}
.tb .r1{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:4px}
.tb .no{font-size:34px;font-weight:800;line-height:1}
.tb .tg{font-size:10px;font-weight:800;padding:5px 10px;border-radius:6px;white-space:nowrap}
.tb .ty{font-size:12px;color:var(--ink2);margin-bottom:11px}
.tb .mt{display:flex;gap:13px;font-size:11px;color:var(--muted);margin-bottom:12px;flex-wrap:wrap}
.tb .wn{background:rgba(156,59,50,.13);border-radius:8px;padding:9px 11px;
font-size:11.5px;margin-bottom:11px;line-height:1.5}
.tabs{display:flex;gap:6px;padding:10px 12px 2px}
.tabs .t{flex:1;text-align:center;padding:9px 0;border-radius:8px;font-size:11px;font-weight:700;
background:var(--surf);border:1px solid var(--line);color:var(--ink2);cursor:pointer}
.tabs .t.on{background:var(--brand);color:#fff;border-color:var(--brand)}
.ov{position:absolute;inset:0;background:rgba(10,16,13,.62);display:none;
align-items:center;justify-content:center;padding:16px;backdrop-filter:blur(2px);z-index:20}
.ov.on{display:flex}
.mo{background:var(--surf);border-radius:18px;width:100%;overflow:hidden;max-height:92%;
display:flex;flex-direction:column;box-shadow:0 20px 60px rgba(0,0,0,.4)}
.mo .mh{padding:14px;text-align:center;background:var(--accent);color:#1A1206}
.mo .mh.r2{background:var(--danger);color:#fff}
.mo .mh .i{font-size:29px;line-height:1;display:block;margin-bottom:6px}
.mo .mh .t{font-size:14.5px;font-weight:800}
.mo .mb{padding:16px;overflow-y:auto}
.mo .mb::-webkit-scrollbar{width:3px}
.rlist .ro{display:flex;align-items:center;gap:11px;padding:14px 13px;border-radius:11px;
border:2px solid var(--line);background:var(--surf2);margin-bottom:8px;cursor:pointer;font-size:13px}
.rlist .ro:active{transform:scale(.98)}
.rlist .ro .e3{font-size:22px}
.rlist .ro.on{border-color:var(--brand);background:var(--okbg)}

